(()=>{
 const get=id=>document.getElementById(id),select=get('agency-select'),message=get('agency-status'),load=get('agency-load'),editor=get('agency-editor'),save=get('agency-save'),remove=get('agency-delete');let items=[],editId=null,busy=false;
 async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not update agency endpoints.');return data}
 function options(selected=''){select.replaceChildren(new Option('Select an agency',''));for(const p of items)select.add(new Option(p.name,p.id));select.value=items.some(p=>p.id===selected)?selected:'';load.disabled=!select.value||busy}
 function populate(p){get('feed-url').value=p.gtfs_url;get('alert-url').value=p.alert_url||'';get('type').value=p.alert_type;get('agency-name').value=p.name;get('agency-gtfs').value=p.gtfs_url;get('agency-alert-type').value=p.alert_type;get('agency-alert-url').value=p.alert_url||'';editId=p.builtin?null:p.id;remove.hidden=!!p.builtin;message.textContent=(p.alert_url?'Endpoints populated. Import both when ready.':'GTFS URL populated; this agency has no saved alert endpoint.')+(p.alert_note?' '+p.alert_note:'')}
 select.addEventListener('change',()=>{const p=items.find(x=>x.id===select.value);load.disabled=!p||busy;if(p)populate(p);else message.textContent='Choose an agency to populate both URLs.'});
 get('agency-new').addEventListener('click',()=>{editId=null;get('agency-name').value='';get('agency-gtfs').value='';get('agency-alert-url').value='';get('agency-alert-type').value='GTFS Realtime alerts feed';remove.hidden=true;get('agency-name').focus();message.textContent='Enter endpoints for a new agency.'});
 save.addEventListener('click',async()=>{save.disabled=true;try{const d=await api('/api/agency-presets',{id:editId,name:get('agency-name').value,gtfs_url:get('agency-gtfs').value,alert_type:get('agency-alert-type').value,alert_url:get('agency-alert-url').value});const name=get('agency-name').value.trim();items=d.items;const p=items.find(x=>x.name===name);options(p?.id);if(p)populate(p);message.textContent='Agency endpoints saved locally.';editor.open=false}catch(e){message.textContent=e.message}finally{save.disabled=false}});
 remove.addEventListener('click',async()=>{if(!editId)return;remove.disabled=true;try{const d=await api('/api/agency-presets/delete',{id:editId});items=d.items;options();editId=null;remove.hidden=true;message.textContent='Agency endpoints removed.'}catch(e){message.textContent=e.message}finally{remove.disabled=false}});
 load.addEventListener('click',async()=>{const p=items.find(x=>x.id===select.value);if(!p||busy)return;busy=true;load.disabled=true;select.disabled=true;populate(p);message.textContent='Importing the GTFS feed…';try{if(!await importFeed()){message.textContent='Feed import failed. See the message below the GTFS URL.';return}if(!p.alert_url){message.textContent='GTFS imported. No alert URL is saved for this agency.';return}get('type').value=p.alert_type;get('alert-url').value=p.alert_url;message.textContent='Feed imported; importing alerts…';if(!await importAlerts()){message.textContent='Feed imported; alerts could not be imported. See the service changes section.';return}message.textContent='GTFS and alerts imported. Assess alerts in Review checks.'}catch(e){message.textContent='Import failed: '+e.message}finally{busy=false;select.disabled=false;load.disabled=!select.value}});
 api('/api/agency-presets').then(d=>{items=d.items;options()}).catch(e=>{message.textContent=e.message});
})();
